std::vector<std::size_t> result;
if (points.empty() || k == 0) return result;

std::vector<std::pair<double, std::size_t>> distances;
distances.reserve(points.size());

// Calculate squared distances to avoid sqrt computation
for (std::size_t i = 0; i < points.size(); ++i) {
    const auto& p = points[i];
    double dx = p.x - searchPoint.x;
    double dy = p.y - searchPoint.y;
    double dz = p.z - searchPoint.z;
    double distSq = dx*dx + dy*dy + dz*dz;
    distances.emplace_back(distSq, i);
}

// Partial sort to get k smallest elements
std::partial_sort(distances.begin(), distances.begin() + std::min(k, distances.size()),
                  distances.end(),
                  [](const auto& a, const auto& b) { return a.first < b.first; });

// Extract indices
result.reserve(k);
for (std::size_t i = 0; i < std::min(k, distances.size()); ++i) {
    result.push_back(distances[i].second);
}
// END_CODE

